import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BGlkWkwp.js";const g=JSON.parse('{"title":"Dropdown","description":"","frontmatter":{},"headers":[],"relativePath":"components/dropdown.md","filePath":"components/dropdown.md"}'),d={name:"components/dropdown.md"};function n(i,e,s,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="dropdown" tabindex="-1">Dropdown <a class="header-anchor" href="#dropdown" aria-label="Permalink to &quot;Dropdown&quot;">​</a></h1><p>Dropdown is the place that opens below a trigger, for a menu or a small picker.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for the menu of a trigger, with <code>menu</code> and a list of <a href="./menu-item">MenuItem</a>, or for a small picker, with <code>bare</code> and content that brings its own container, such as a <a href="./color-picker">ColorPicker</a>. A few settings are a <a href="./popover">Popover</a>, which is built on it; the actions of an item are a <a href="./kebab">Kebab</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>trigger</code></td><td>required</td><td>The trigger: a snippet of <code>(toggle, open)</code></td></tr><tr><td><code>panel</code></td><td>required</td><td>The content: a snippet of <code>(close)</code></td></tr><tr><td><code>menu</code></td><td><code>false</code></td><td>The content is a list of MenuItem</td></tr><tr><td><code>bare</code></td><td><code>false</code></td><td>The content has its own container</td></tr><tr><td><code>align</code></td><td><code>end</code></td><td>The edge of the trigger it lines up with</td></tr><tr><td><code>up</code></td><td><code>false</code></td><td>Opens above the trigger, below only without room</td></tr><tr><td><code>openInitially</code></td><td><code>false</code></td><td>Open from the start</td></tr><tr><td><code>menuMaxWidth</code></td><td></td><td>The greatest width, a CSS length</td></tr><tr><td><code>block</code></td><td><code>false</code></td><td>The trigger is as wide as its container</td></tr><tr><td><code>role</code></td><td><code>anchor</code></td><td><code>box</code> for a control, <code>icon-button</code> for an icon button</td></tr><tr><td><code>onOpenChange</code></td><td></td><td>Called whenever it opens or closes</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The place is a popover in the top layer, so a modal or a panel around the trigger does not hide it. It opens gap-xs below the trigger, lined up with its <code>align</code> edge, or above it when there is less room below than its height (or 120px); it stays gap-md inside the window, the margin of a page on a narrow screen. With <code>up</code> the two sides change places: it opens above the trigger, and below it when there is less room above than its height (or 120px) and more below. While it is open it follows the trigger: when the trigger moves (a scroll, a change of layout, the stylesheets arriving late), it is placed again. A trigger inside a bar (an element with <code>role=&quot;toolbar&quot;</code> or <code>data-role=&quot;toolbar&quot;</code>: a Toolbar, a Topbar or a Drawbar) opens it from the bar&#39;s edge instead of its own, still lined up with the trigger at the sides. From a vertical bar (<code>aria-orientation=&quot;vertical&quot;</code>, a Drawbar standing in a column) it opens beside the bar, gap-xs from its left edge, or from its right edge when there is no room on the left, lined up with the top of the trigger; <code>up</code> does not apply there. With <code>menu</code>, it has the surface of a <a href="./menu">Menu</a> and <code>role=&quot;menu&quot;</code>, the first item takes the focus, the arrow keys move the focus between the items and wrap at the ends, and Home and End go to the first and the last. A press outside, Escape or Tab closes it; Escape and Tab return the focus to the trigger of a menu. Escape goes no further, so a modal around it stays open. Each time it opens or closes, the wrapper of the trigger dispatches a bubbling <code>kata-menu-toggle</code> event with <code>detail: { open }</code>, so the element around the trigger (a <a href="./tree-row">TreeRow</a>) knows a menu of its own is open.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/dropdown/" title="Dropdown" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/dropdown/" target="_blank" rel="noopener">Dropdown</a></figcaption></figure>',10)])])}const u=t(d,[["render",n]]);export{g as __pageData,u as default};
